private void enlarge(final int size){
    // Reject non-positive size to avoid unnecessary work or errors.
    if (size <= 0){
        return;
    }

    // Calculate the desired capacity after adding the requested size.
    int currentLen = (this.data != null) ? this.len : 0;
    int desiredLen = currentLen + size;
    int currentCap = (this.data != null) ? this.data.length : 0;

    // If the current buffer already satisfies the requirement, nothing to do.
    if (desiredLen <= currentCap){
        return;
    }

    // Compute new capacity: double the existing one or just the required size,
    // whichever is larger. Avoid potential overflow when doubling.
    int newCap = Math.max(currentCap * 2, desiredLen);
    if (newCap < desiredLen){
        newCap = desiredLen;
    }

    try{
        // Allocate a new buffer and copy existing data.
        byte[] newBuffer = new byte[newCap];
        if (this.data != null && currentLen > 0){
            System.arraycopy(this.data, 0, newBuffer, 0, currentLen);
        }
        this.data = newBuffer;
    }catch(OutOfMemoryError e){
        // Wrap low‑level error in a RuntimeException with an informative message.
        throw new RuntimeException("Unable to enlarge byte vector to capacity " + newCap, e);
    }
}

