public String format(LoggingEvent event){
    // Validate input
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent must not be null");
    }

    // Retrieve the conversion pattern (assumed to be defined in the containing class)
    String pattern = this.conversionPattern;
    if (pattern == null || pattern.isEmpty()) {
        return "";
    }

    StringBuilder result = new StringBuilder();

    try {
        for (int i = 0; i < pattern.length(); i++) {
            char ch = pattern.charAt(i);

            if (ch == '%') {
                i++; // Move to the specifier (or modifier)
                if (i >= pattern.length()) {
                    // Trailing '%' - just append it
                    result.append('%');
                    break;
                }

                // Handle optional '-' flag (left alignment)
                boolean leftAlign = false;
                if (pattern.charAt(i) == '-') {
                    leftAlign = true;
                    i++;
                }

                // Read optional width number
                int width = 0;
                while (i < pattern.length() && Character.isDigit(pattern.charAt(i))) {
                    width = width * 10 + (pattern.charAt(i) - '0');
                    i++;
                }

                if (i >= pattern.length()) {
                    // Pattern ended unexpectedly
                    result.append('%');
                    if (leftAlign) {
                        result.append('-');
                    }
                    if (width > 0) {
                        result.append(width);
                    }
                    break;
                }

                char spec = pattern.charAt(i);
                String value = "";

                switch (spec) {
                    case 'm': // Message
                        value = event.getMessage();
                        break;
                    case 'p': // Priority/Level
                        value = event.getLevel().toString();
                        break;
                    case 'c': // Logger category/name
                        value = event.getLoggerName();
                        break;
                    case 't': // Thread name
                        value = event.getThreadName();
                        break;
                    case 'd': // Date
                        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
                        value = sdf.format(new java.util.Date(event.getTimeStamp()));
                        break;
                    case 'n': // Newline
                        result.append(System.lineSeparator());
                        continue; // skip appending value
                    case '%': // Literal percent
                        result.append('%');
                        continue;
                    default:
                        // Unknown specifier – include it verbatim
                        result.append('%').append(spec);
                        continue;
                }

                // Apply width formatting if necessary
                if (width > 0) {
                    String fmt = leftAlign ? "%-" + width + "s" : "%" + width + "s";
                    result.append(String.format(fmt, value));
                } else {
                    result.append(value);
                }
            } else {
                result.append(ch);
            }
        }

        return result.toString();
    } catch (Exception e) {
        // On any formatting error, return a diagnostic string
        return "FORMAT_ERROR: " + e.getMessage();
    }
}

