private int parseEndOfLine(String headerPart, int end) {
    // Validate inputs
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart must not be null");
    }
    if (end < -1 || end >= headerPart.length()) {
        throw new IllegalArgumentException("end index out of bounds: " + end);
    }

    // Search for the CRLF sequence starting after the given index
    int startSearch = end + 1;
    int crlfIndex = headerPart.indexOf("\r\n", startSearch);

    // Return the index of the CRLF sequence (or -1 if not found)
    return crlfIndex;
}

