public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }

    // If the file doesn't exist there's nothing to schedule.
    if (!file.exists()) {
        return;
    }

    // If the file is a directory, schedule all contained files first.
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child); // recurse into subdirectories
            }
        }
    }

    // Schedule this file (or directory) for deletion on JVM exit.
    try {
        file.deleteOnExit();
    } catch (SecurityException se) {
        // Wrap the security exception in an IOException to match the declared throws clause.
        throw new IOException("Unable to register " + file + " for deletion on exit", se);
    }
}

