@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and resultMap must not be null.");
    }
    try {
        // Add all vertices from the map to the graph
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            V vertex = entry.getValue();
            if (vertex == null) continue;
            if (!target.containsVertex(vertex)) {
                target.addVertex(vertex);
            }
        }

        // Build a complete bipartite graph from the vertices.
        // We split the vertices list into two halves: left and right partitions.
        List<V> vertices = new ArrayList<>(resultMap.values());
        int n = vertices.size();
        if (n < 2) {
            return; // No edges to add
        }

        int half = n / 2;
        List<V> left = vertices.subList(0, half);
        List<V> right = vertices.subList(half, n);

        for (V u : left) {
            for (V v : right) {
                if (!target.containsEdge(u, v)) {
                    target.addEdge(u, v);
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to generate complete bipartite graph.", e);
    }
}

protected int findByte(byte value, int pos) {
    // Validate the buffer reference
    if (buffer == null) {
        return -1;
    }
    int len = buffer.length;
    // Position must be within the bounds of the buffer
    if (pos < 0 || pos >= len) {
        return -1;
    }
    // Search for the byte starting at the specified position
    for (int i = pos; i < len; i++) {
        if (buffer[i] == value) {
            return i; // Found the byte, return its position
        }
    }
    // Value not found
    return -1;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("OutputStream, Schema, and LinkedBuffer must not be null.");
    }

    // Compute the serialized size of the message using the provided schema and buffer.
    final int size;
    try {
        size = schema.getSerializedSize(message, buffer);
    } catch (RuntimeException | Error e) {
        throw new IOException("Unable to compute serialized size.", e);
    }

    // Write the size prefix and the message itself.
    CodedOutputStream coded = CodedOutputStream.newInstance(out);
    coded.writeRawVarint32(size);
    try {
        schema.writeTo(message, coded);
    } catch (RuntimeException | Error e) {
        throw new IOException("Error writing message to output.", e);
    }

    coded.flush();
    return size;
}

