void insertBefore(Bucket bucket){
    if (bucket == null) {
        throw new NullPointerException("bucket cannot be null");
    }
    if (bucket == this) {
        throw new IllegalArgumentException("Cannot insert before itself");
    }

    // Detach this bucket from its current neighbors, if any
    if (prev != null) {
        prev.next = next;
    }
    if (next != null) {
        next.prev = prev;
    }

    // Insert this bucket before the provided bucket
    Bucket prevBucket = bucket.prev;
    this.prev = prevBucket;
    this.next = bucket;
    bucket.prev = this;
    if (prevBucket != null) {
        prevBucket.next = this;
    }
}

