public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null) {
        return null;
    }

    Mappings diff = new Mappings();
    try {
        // Attempt to retrieve the properties map from the input mappings.
        // The structure is assumed to be a Map<String, Object> under the "properties" key,
        // similar to an Elasticsearch mapping representation.
        Object propertiesObj = mappings.get("properties");
        if (propertiesObj instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> properties = (Map<String, Object>) propertiesObj;

            for (Map.Entry<String, Object> entry : properties.entrySet()) {
                String fieldName = entry.getKey();

                // Skip the _source configuration to avoid index update conflicts.
                if ("_source".equals(fieldName)) {
                    continue;
                }

                // The logic for determining "fields that do not exist" in the
                // history mapping is not specified beyond excluding _source.
                // Therefore, we simply include all other fields in the diff.
                diff.put(fieldName, entry.getValue());
            }
        }
    } catch (Exception e) {
        // In case of any reflection or casting issues, return an empty diff.
        // No exception is propagated to the caller as per the error handling policy.
    }

    return diff;
}

