public static void createConfigurationDirectory(){
    try {
        String osName = System.getProperty("os.name");
        String osVersion = System.getProperty("os.version");
        String path;
        if (osName != null && osName.startsWith("Windows") &&
            osVersion != null && osVersion.startsWith("5.0")) {
            // Windows 2000: create "lf5" inside the parent of user.home (normally Documents and Settings)
            String userHome = System.getProperty("user.home");
            java.io.File userHomeFile = new java.io.File(userHome);
            java.io.File parent = userHomeFile.getParentFile();
            String parentPath = parent != null ? parent.getAbsolutePath()
                                               : (System.getenv("HOMEDRIVE") != null ?
                                                  System.getenv("HOMEDRIVE") : System.getProperty("user.home"));
            path = parentPath + java.io.File.separator + "lf5";
        } else {
            // Other platforms: create "lf5" inside the user.home directory
            path = System.getProperty("user.home") + java.io.File.separator + "lf5";
        }
        java.io.File configDir = new java.io.File(path);
        if (!configDir.exists()) {
            if (!configDir.mkdirs()) {
                throw new java.io.IOException("Unable to create configuration directory: " + path);
            }
        }
    } catch (Exception e) {
        // Logging is optional; in many contexts swallowing the exception is acceptable
        // e.printStackTrace();
    }
}

public long readLong(final int offset){
    if (offset < 0 || offset + 8 > this.bytes.length) {
        throw new IllegalArgumentException("Invalid offset for reading long: " + offset);
    }
    final byte[] b = this.bytes;
    return ((long)(b[offset] & 0xFF) << 56) |
           ((long)(b[offset+1] & 0xFF) << 48) |
           ((long)(b[offset+2] & 0xFF) << 40) |
           ((long)(b[offset+3] & 0xFF) << 32) |
           ((long)(b[offset+4] & 0xFF) << 24) |
           ((long)(b[offset+5] & 0xFF) << 16) |
           ((long)(b[offset+6] & 0xFF) << 8) |
           ((long)(b[offset+7] & 0xFF));
}

public boolean equals(final byte[] data,int offset,final int len){
    // Quick checks for null pointers
    if (data == null || this.data == null) {
        return false;
    }
    // Check bounds for the input array
    if (len < 0 || offset < 0 || offset + len > data.length) {
        return false;
    }
    // Length mismatch between the internal array and the requested slice
    if (len != this.data.length) {
        return false;
    }
    // Element‑by‑element comparison
    for (int i = 0; i < len; i++) {
        if (this.data[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

public static Byte[] nullToEmpty(final Byte[] array){
