    // This avoids allocating a new array unnecessarily and conserves memory.
    if (array == null || array.length == 0) {
        return EMPTY_BYTES; // EMPTY_BYTES must be a public static final Byte[] defined elsewhere in the class.
    }
    // Otherwise, return the original array as is.
    return array;
}

public synchronized void send(final String message) {
    if (message == null) {
        throw new IllegalArgumentException("message cannot be null");
    }

    // Ensure there's a client list before proceeding
    if (telnetClients == null || telnetClients.isEmpty()) {
        return;
    }

    final String formatted = message + "\r\n";
    // Iterate over the list using an iterator so we can safely remove problematic clients
    for (Iterator<PrintWriter> it = telnetClients.iterator(); it.hasNext(); ) {
        PrintWriter writer = it.next();
        try {
            writer.print(formatted);
            writer.flush();
        } catch (Exception e) {
            // Remove the writer that caused the exception and close its resources
            it.remove();
            try {
                writer.close();
            } catch (Exception closeEx) {
                // ignore, as we're already handling a failure
            }
        }
    }
}

