public void put(LoggingEvent o) {
    if (o == null) {
        return;
    }

    // Assuming a circular buffer implementation with fields:
    //   LoggingEvent[] buffer;   // the underlying array
    //   int writePos;            // index of next write
    //   int readPos;             // index of next read
    // The buffer is considered full when the next position would collide with the read position.
    // In that case we silently drop the event, as per the contract.
    int nextPos = (writePos + 1) % buffer.length;
    if (nextPos == readPos) {
        // Buffer full – silently drop the event
        return;
    }

    buffer[writePos] = o;
    writePos = nextPos;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    try {
        if (start > end) {
            throw new IllegalArgumentException("start must be less than or equal to end");
        }
        if (start == end) {
            // No duration to split
            return ranges;
        }

        long remaining = end - start;
        if (remaining <= FETCH_DATA_DURATION) {
            ranges.add(new TimeRange(start, end));
            return ranges;
        }

        long numIntervals = (remaining + FETCH_DATA_DURATION - 1) / FETCH_DATA_DURATION; // ceil
        long currentStart = start;
        for (int i = 0; i < numIntervals; i++) {
            long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
            ranges.add(new TimeRange(currentStart, currentEnd));
            currentStart = currentEnd;
        }
    } catch (Exception e) {
        throw new RuntimeException("Error building time ranges", e);
    }
    return ranges;
}

