            result[i] = b.byteValue();
        }
        return result;
    } catch (RuntimeException e) {
        // Re-throwing ensures callers see the original NPE if thrown
        throw e;
    }
}

static long compressTimeBucket(long timeBucket,int dayStep){
    try{
        if(dayStep <= 0){
            throw new IllegalArgumentException("dayStep must be positive");
        }
        long year  = timeBucket / 10000;
        long month = (timeBucket / 100) % 100;
        long day   = timeBucket % 100;
        if(day < 1 || day > 31 || month < 1 || month > 12){
            throw new IllegalArgumentException("Invalid date in timeBucket");
        }
        long compressedDay = ((day - 1) / dayStep) * dayStep + 1;
        return year * 10000 + month * 100 + compressedDay;
    }catch(Exception e){
        throw new RuntimeException("Error compressing time bucket", e);
    }
}

/**
 * Computes the size of the UTF‑8 encoding for the subsection of {@code str}
 * that starts at {@code index} and spans {@code len} code units.
 *
 * <p>This method evaluates the number of bytes that would result from
 * encoding the specified substring in UTF‑8. It handles surrogate pairs
 * correctly: a valid surrogate pair contributes 4 bytes, while an
 * unpaired surrogate contributes 3 bytes (the size of a BMP code point).
 * The method performs bounds checking on the arguments and throws an
 * {@link IndexOutOfBoundsException} if the requested range is
 * outside the bounds of {@code str}. If {@code str} is {@code null},
 * a {@link NullPointerException} is thrown.</p>
 *
 * @param str   the character sequence to analyze; must not be {@code null}
 * @param index the starting index of the range (inclusive); must be
 *              non‑negative and less than or equal to {@code str.length()}
 * @param len   the number of code units to include; must be non‑negative
 *              and {@code index + len} must not exceed {@code str.length()}
 * @return the total number of bytes required to encode the specified
 *         subsection of {@code str} in UTF‑8
 * @throws IndexOutOfBoundsException if {@code index} or {@code len} are
 *                                   out of bounds
 * @throws NullPointerException if {@code str} is {@code null}
 */
public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("The CharSequence 'str' must not be null");
    }

    final int strLen = str.length();

    if (index < 0 || len < 0 || index > strLen || len > strLen - index) {
        throw new IndexOutOfBoundsException(
                "Invalid range: index=" + index + ", len=" + len + ", str.length()=" + strLen);
    }

    int byteCount = 0;
    final int end = index + len;

    for (int i = index; i < end; ) {
        final int codePoint = str.codePointAt(i);
        if (codePoint <= 0x7F) {
            byteCount += 1;
        } else if (codePoint <= 0x7FF) {
            byteCount += 2;
        } else if (codePoint <= 0xFFFF) {
            byteCount += 3;
        } else {
            byteCount += 4;
        }
        i += Character.charCount(codePoint);
    }

    return byteCount;
}

