    if(str == null){
        return null;
    }

    int length = str.length();

    // Adjust negative start to 0
    if(start < 0){
        start = 0;
    }

    // Adjust end beyond string length to the actual length
    if(end > length){
        end = length;
    }

    // If start exceeds length after adjustments, clamp it to length
    if(start > length){
        start = length;
    }

    // If the start position is greater than the end position, return empty string
    if(start > end){
        return "";
    }

    try{
        // Perform the substring operation safely
        return str.substring(start, end);
    }catch(Exception e){
        // In the unlikely event of an exception, return empty string to avoid propagating errors
        return "";
    }
}

