public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        return null;
    }
    String baseValue = props.getProperty(key);
    if (baseValue == null) {
        return null;
    }
    try {
        String value = baseValue;
        Pattern pattern = Pattern.compile("\\$\\{([^}]+)\\}");
        int maxDepth = 10; // prevent infinite recursion
        for (int depth = 0; depth < maxDepth; depth++) {
            Matcher matcher = pattern.matcher(value);
            boolean found = false;
            StringBuffer sb = new StringBuffer();
            while (matcher.find()) {
                found = true;
                String varName = matcher.group(1);
                String replacement = props.getProperty(varName);
                if (replacement == null) {
                    // Leave placeholder unchanged if property not found
                    replacement = matcher.group(0);
                }
                replacement = Matcher.quoteReplacement(replacement);
                matcher.appendReplacement(sb, replacement);
            }
            matcher.appendTail(sb);
            value = sb.toString();
            if (!found) {
                break;
            }
        }
        return value;
    } catch (Exception e) {
        // Return the original value if substitution fails
        return baseValue;
    }
}

