@Override public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("data array is null");
    }
    if (off < 0 || len < 0 || off > b.length || len > (b.length - off)) {
        throw new IndexOutOfBoundsException("Offset or length out of bounds");
    }
    if (len == 0) {
        return;
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        byte[] newBuf;
        if (buf.length == 0) {
            newBuf = new byte[newCount];
        } else {
            newBuf = new byte[Math.max(buf.length << 1, newCount)];
        }
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

public static final <V> void swap(V[] arr, int i, int j) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null.");
    }
    int len = arr.length;
    if (i < 0 || j < 0 || i >= len || j >= len) {
        throw new IndexOutOfBoundsException(
                String.format("Indices out of bounds: i=%d, j=%d, length=%d", i, j, len));
    }
    if (i == j) {
        return; // nothing to do
    }
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

public Boolean isPartialContentResponse() {
    // Attempt to read a plain status code field named "statusCode"
    try {
        java.lang.reflect.Field statusField = this.getClass().getDeclaredField("statusCode");
        statusField.setAccessible(true);
        Object val = statusField.get(this);
        if (val instanceof Number) {
            return (((Number) val).intValue() == 206);
        }
    } catch (NoSuchFieldException | IllegalAccessException e) {
        // Field not found or inaccessible – try other strategies
    }

    // Attempt to find an HTTP response object that provides a status code method
    try {
        java.lang.reflect.Field httpField = this.getClass().getDeclaredField("httpResponse");
        httpField.setAccessible(true);
        Object resp = httpField.get(this);
        if (resp != null) {
            java.lang.reflect.Method statusMethod = resp.getClass().getMethod("statusCode");
            Object rc = statusMethod.invoke(resp);
            if (rc instanceof Number) {
                return (((Number) rc).intValue() == 206);
            }
        }
    } catch (Exception e) {
        // Any exception (field not found, method invocations, etc.) – ignore
    }

    // Default to false if no indication of partial content was found
    return Boolean.FALSE;
}

