protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Validate arguments
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("Source vertex, target vertex, and edge must not be null.");
    }

    // Lazily initialize the index if it hasn't been set up yet
    if (edgeIndex == null) {
        edgeIndex = new java.util.HashMap<>();
    }

    // Create a unique key based on the identity of the vertices
    java.lang.String key = Integer.toHexString(System.identityHashCode(sourceVertex))
            + "|" + Integer.toHexString(System.identityHashCode(targetVertex));

    // Retrieve or create the set of edges for this vertex pair
    java.util.Set<E> edges = edgeIndex.get(key);
    if (edges == null) {
        edges = new java.util.HashSet<>();
        edgeIndex.put(key, edges);
    }

    // Add the edge to the set (duplicates are automatically ignored)
    edges.add(e);
}

