    String[] dst = new String[src.length];
    for (int i = 0; i < src.length; i++) {
        try {
            String s = src[i];
            if (s == null) {
                dst[i] = null;
                continue;
            }
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < s.length(); j++) {
                char c = s.charAt(j);
                if (Character.isLetter(c)) {
                    sb.append(Character.toLowerCase(c));
                }
                // Non-letter characters are omitted to enforce only lower-case letters.
            }
            dst[i] = sb.toString();
        } catch (Exception e) {
            // In case of unexpected errors, set the element to null and continue.
            dst[i] = null;
        }
    }
    return dst;
}

