        double minY = box.getMinY();
        double maxY = box.getMaxY();
        double midX = (minX + maxX) / 2.0;

        Box2D left = new Box2D(minX, minY, midX, maxY);
        Box2D right = new Box2D(midX, minY, maxX, maxY);

        return new Pair<>(left, right);
    } catch (Exception e) {
        throw new IllegalStateException("Failed to split the box along the X axis", e);
    }
}

private void enlarge(final int size){
    // size is the number of additional bytes we want to accommodate
    if (size <= 0) {
        // nothing to do for non-positive request
        return;
    }
    try {
        // compute the total number of bytes that will be used after enlargement
        int required = Math.addExact(this.size, size);
        // if the current backing array already has enough space, nothing to do
        if (array != null && required <= array.length) {
            return;
        }
        // If there is no backing array yet, create one large enough
        if (array == null || array.length == 0) {
            // start with a small default capacity or exactly what's needed
            int initCap = Math.max(16, required);
            array = new byte[initCap];
            return;
        }

        // Grow the backing array.  A common strategy is to double its size
        // until it can accommodate the required number of bytes.
        int newCap = array.length * 2;
        if (newCap < required) {
            newCap = required;
        }

        // Detect potential overflow that would lead to an illegal negative array size
        if (newCap < 0) {
            newCap = Integer.MAX_VALUE; // use maximal array size
        }

        byte[] tmp = new byte[newCap];
        System.arraycopy(array, 0, tmp, 0, this.size);
        array = tmp;
    } catch (ArithmeticException ex) {
        // The requested size overflows an int; treat it as too large to allocate
        throw new OutOfMemoryError("Requested byte vector size exceeds maximum array size");
    }
}

