    // If first two characters are both uppercase, leave unchanged (to reverse Introspector.decapitalize behavior)
    if (name.length() > 1 && Character.isUpperCase(name.charAt(0)) && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    char[] chars = name.toCharArray();
    chars[0] = Character.toUpperCase(chars[0]);
    return new String(chars);
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput must not be null");
    }
    if (node == null) {
        return 0;
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    try {
        while (current != null) {
            // We assume LinkedBuffer has the standard fields used by Q-RTC style buffers:
            // - byte[] buf : underlying storage
            // - int start : start index of valid data
            // - int end : end index (exclusive) of valid data
            // - LinkedBuffer next : next buffer in the chain
            int len = current.end - current.start;
            if (len > 0) {
                out.write(current.buf, current.start, len);
                totalSize += len;
            }
            current = current.next;
        }
    } catch (IOException e) {
        // Propagate IOException while also ensuring resource safety if needed
        throw e;
    } catch (Exception e) {
        // Wrap any unexpected runtime exception into an IOException
        throw new IOException("Error writing LinkedBuffer to DataOutput", e);
    }
    return totalSize;
}

