@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (value == null) {
        return null;
    }
    // Support primitive char and Character wrapper
    if (type == Character.class || type == char.class) {
        if (value instanceof Character) {
            return value;
        } else if (value instanceof String) {
            String s = (String) value;
            if (s.length() == 1) {
                return Character.valueOf(s.charAt(0));
            } else {
                throw new IllegalArgumentException("Cannot convert String of length > 1 to Character");
            }
        } else if (value instanceof Number) {
            int intVal = ((Number) value).intValue();
            return Character.valueOf((char) intVal);
        } else {
            throw new IllegalArgumentException("Cannot convert value of type " + value.getClass().getName() + " to Character");
        }
    } else {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }
}

public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
    // Return false for null string or null list. This avoids NullPointerExceptions.
    if (str == null || searchStrArray == null) {
        return false;
    }

    // Precompute the lower-case representation of the target string for efficiency.
    final String lowerStr = str.toLowerCase(Locale.ROOT);

    // Iterate over each search string in the array.
    for (String search : searchStrArray) {
        if (search == null) {
            // Skip null entries as they cannot match anything.
            continue;
        }

        // Convert the search string to lower-case once.
        final String lowerSearch = search.toLowerCase(Locale.ROOT);

        // Check if the lower-case target string contains the lower-case search string.
        // If found, we can immediately return true.
        if (lowerStr.contains(lowerSearch)) {
            return true;
        }
    }

    // If none of the search strings matched, return false.
    return false;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = Math.max(desiredCapacity, 2);
    // Bound for 11% increase if desiredCapacity >= 1000
    int maxCandidate = desiredCapacity >= 1000
            ? (int) Math.ceil(desiredCapacity * 1.11)  // round up to avoid missing a prime slightly above 11%
            : Integer.MAX_VALUE;
    while (candidate <= maxCandidate) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate++;
    }
    // If no prime found within the 11% interval, fall back to a larger prime
    // but still guarantee the result is >= desiredCapacity
    candidate = maxCandidate + 1;
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate++;
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; (long) i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

