public static Object findFirstMatch(Collection source, Collection candidates) {
    // Handle invalid inputs gracefully
    if (source == null || candidates == null) {
        return null;
    }
    try {
        // Iterate over candidates in their natural order
        for (Object candidate : candidates) {
            // Return the first candidate found in source
            if (source.contains(candidate)) {
                return candidate;
            }
        }
        // No match found
        return null;
    } catch (Exception e) {
        // In case of unexpected runtime exceptions, return null rather than propagating
        return null;
    }
}

