@Override
public String readString() throws IOException {
    // Attempt to read a string that is encoded as a 4‑byte big‑endian length
    // followed by that many bytes of UTF‑8 data.
    try {
        // We assume the underlying stream implements DataInput so that
        // readInt() is available for reading the length prefix.
        int length = readInt(); // throws IOException if read fails
        if (length < 0) {
            throw new IOException("Invalid string length: " + length);
        }
        byte[] buf = new byte[length];
        int pos = 0;
        while (pos < length) {
            int n = read(buf, pos, length - pos); // delegate to the stream’s read method
            if (n == -1) {
                throw new EOFException("Unexpected end of input while reading string");
            }
            pos += n;
        }
        // Construct the string using UTF‑8. Charset not imported, so we use the
        // legacy constructor that accepts a charset name.
        return new String(buf, "UTF-8");
    } catch (UnsupportedEncodingException e) {
        // This should not happen on a JVM that supports UTF‑8.
        throw new IOException("UTF‑8 not supported", e);
    }
}

private static int digitValue(final char c) {
    // Numeric digits
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    // Uppercase letters A–Z
    if (c >= 'A' && c <= 'Z') {
        return 10 + (c - 'A');
    }
    // Lowercase letters a–z
    if (c >= 'a' && c <= 'z') {
        return 10 + (c - 'a');
    }
    // Non‑ASCII or invalid characters
    return -1;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> contentMap = new LinkedHashMap<>();
    try {
        if (jsonObject == null) {
            return contentMap;
        }
        for (Map.Entry<String, com.google.gson.JsonElement> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            com.google.gson.JsonElement valueElement = entry.getValue();
            if (valueElement == null || valueElement.isJsonNull()) {
                contentMap.put(key, null);
                continue;
            }
            Object value;
            if (valueElement.isJsonPrimitive()) {
                com.google.gson.JsonPrimitive prim = valueElement.getAsJsonPrimitive();
                if (prim.isBoolean()) {
                    value = prim.getAsBoolean();
                } else if (prim.isNumber()) {
                    // Preserve the most specific number type
                    Number num = prim.getAsNumber();
                    try {
                        value = num.intValueExact();
                    } catch (ArithmeticException e) {
                        try {
                            value = num.longValueExact();
                        } catch (ArithmeticException ex) {
                            // Fall back to double
                            value = num.doubleValue();
                        }
                    }
                } else if (prim.isString()) {
                    value = prim.getAsString();
                } else {
                    value = prim.getAsString();
                }
            } else if (valueElement.isJsonArray() || valueElement.isJsonObject()) {
                // Keep the JsonElement as-is for complex structures
                value = valueElement;
            } else {
                value = valueElement.toString();
            }
            // Special handling for "ats" field if present
            if ("ats".equalsIgnoreCase(key) && value != null) {
                // If value is a string that can be parsed as a long timestamp, keep it; otherwise leave as string
                if (value instanceof String) {
                    try {
                        Long.parseLong((String) value);
                    } catch (NumberFormatException nfe) {
                        // leave as string
                    }
                }
            }
            contentMap.put(key, value);
        }
    } catch (Exception e) {
        // In case of unexpected errors, return an empty map
        contentMap.clear();
    }
    return contentMap;
}

