public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch != '\\' || i == len - 1) {
            sb.append(ch);
            continue;
        }
        // Escape sequence starts with backslash
        char next = str.charAt(++i);
        switch (next) {
            case 'b':
                sb.append('\b');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'n':
                sb.append('\n');
                break;
            case 'f':
                sb.append('\f');
                break;
            case 'r':
                sb.append('\r');
                break;
            case '\"':
                sb.append('\"');
                break;
            case '\'':
                sb.append('\'');
                break;
            case '\\':
                sb.append('\\');
                break;
            case 'u':
                // Handle one or more 'u' characters
                int uCount = 1;
                while (i + 1 < len && str.charAt(i + 1) == 'u') {
                    i++;
                    uCount++;
                }
                if (i + 4 >= len) {
                    throw new Exception("Invalid Unicode escape sequence: insufficient hex digits");
                }
                String hex = str.substring(i + 1, i + 5);
                int codePoint;
                try {
                    codePoint = Integer.parseInt(hex, 16);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid Unicode escape sequence: " + hex, e);
                }
                sb.append((char) codePoint);
                i += 4; // advance past the hex digits
                break;
            default:
                // If next is octal digit 0-7, handle up to 3 digits
                if (next >= '0' && next <= '7') {
                    int octal = next - '0';
                    int count = 1;
                    while (count < 3 && i + 1 < len) {
                        char c = str.charAt(i + 1);
                        if (c >= '0' && c <= '7') {
                            octal = (octal << 3) + (c - '0');
                            i++;
                            count++;
                        } else {
                            break;
                        }
                    }
                    sb.append((char) octal);
                } else {
                    // Not a recognized escape, keep the literal next character
                    sb.append(next);
                }
                break;
        }
    }
    return sb.toString();
}

