public short readShort(final int offset) {
    try {
        // Combine two consecutive bytes into a signed short.
        // The first byte is the high byte, the second is the low byte.
        return (short)((b[offset] << 8) | (b[offset + 1] & 0xFF));
    } catch (ArrayIndexOutOfBoundsException ex) {
        // The offset (or offset+1) is outside the byte array bounds.
        // ASM uses StringIndexOutOfBoundsException to signal this situation.
        throw new StringIndexOutOfBoundsException(offset);
    }
}

private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    // Handle null array: create a new array of size 1 with the specified component type
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new NullPointerException("When array is null, newArrayComponentType must not be null");
        }
        return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
    }

    // Validate that the given object is actually an array
    Class<?> arrayClass = array.getClass();
    if (!arrayClass.isArray()) {
        throw new IllegalArgumentException("Provided object is not an array");
    }

    Class<?> componentType = arrayClass.getComponentType();
    int originalLength = java.lang.reflect.Array.getLength(array);
    int newLength = originalLength + 1;

    Object newArray = java.lang.reflect.Array.newInstance(componentType, newLength);

    try {
        // Copy existing elements and leave the last element as default (zero/null)
        System.arraycopy(array, 0, newArray, 0, originalLength);
    } catch (IllegalArgumentException | IllegalAccessException e) {
        // Wrap and rethrow as a runtime exception for unexpected reflection errors
        throw new RuntimeException("Failed to copy array elements", e);
    }

    return newArray;
}

private int computeBinaryLog(int n){
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be positive: " + n);
    }
    try {
        // floor(log2(n)) + 1 equals the position of the highest set bit (1-indexed)
        return 32 - Integer.numberOfLeadingZeros(n);
    } catch (Exception e) {
        // Wrap any unexpected runtime issue
        throw new RuntimeException("Failed to compute binary log for n=" + n, e);
    }
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        throw new IllegalArgumentException("Input sets must not be null");
    }
    // Choose the smaller set as the base to reduce memory usage
    Set<V> result;
    if (set1.size() <= set2.size()) {
        result = new HashSet<>(set1);
        result.retainAll(set2);
    } else {
        result = new HashSet<>(set2);
        result.retainAll(set1);
    }
    return result;
}

static String[] toNoNullStringArray(Collection<?> collection) {
    if (collection == null) {
        throw new IllegalArgumentException("The collection must not be null.");
    }
    java.util.List<String> list = new java.util.ArrayList<>(collection.size());
    for (Object element : collection) {
        if (element != null) {
            // String.valueOf will call element.toString() safely for non-null objects
            list.add(String.valueOf(element));
        }
    }
    return list.toArray(new String[0]);
}

