        }
    }
    return true;
}

protected Object filter(Object msg) {
    // Guard against null messages; simply return null to avoid processing.
    if (msg == null) {
        return null;
    }

    try {
        // Create a BroadcastFilter instance and delegate the filtering logic.
        // If BroadcastFilter is a singleton or already available via a getter,
        // replace the following line accordingly.
        BroadcastFilter broadcastFilter = new BroadcastFilter();
        return broadcastFilter.filter(msg);
    } catch (Throwable t) {
        // Any exception during filtering should be caught and handled gracefully.
        // Returning null ensures the caller can detect a failure to filter.
