private JsonObject convertProperties(List<KeyStringValuePair> properties){
    JsonObject result = new JsonObject();
    if (properties == null) {
        return result;
    }
    for (KeyStringValuePair kvp : properties) {
        if (kvp == null) {
            continue;
        }
        try {
            String key = kvp.getKey();
            String value = kvp.getValue();
            if (key == null || key.isEmpty()) {
                continue;
            }
            if (value == null) {
                result.add(key, JsonNull.INSTANCE);
            } else {
                result.addProperty(key, value);
            }
        } catch (Exception e) {
            // If the key/value extraction fails for a particular entry,
            // skip it and continue with the next entry.
            continue;
        }
    }
    return result;
}

protected int removeUnusedNodes() {
    int removed = 0;
    try {
        if (root == null) {
            return 0;
        }
        removed = removeUnusedNodesHelper(root);
    } catch (Exception e) {
        throw new RuntimeException("Error while removing unused nodes", e);
    }
    return removed;
}

private int removeUnusedNodesHelper(Category node) {
    int removed = 0;
    if (node == null) {
        return 0;
    }
    try {
        List<Category> children = node.getChildren();
        // iterate from end to safely remove elements while iterating
        for (int i = children.size() - 1; i >= 0; i--) {
            Category child = children.get(i);
            if (!child.isActive()) {
                children.remove(i);
                removed++;
            } else {
                removed += removeUnusedNodesHelper(child);
            }
        }
    } catch (Exception e) {
        // Log or rethrow as needed; here we propagate as runtime
        throw new RuntimeException("Failed to process node: " + node, e);
    }
    return removed;
}

