public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non‑negative");
    }

    // Ensure sufficient capacity
    int required = count + byteLength;
    if (required > array.length) {
        int newCap = Math.max(array.length * 2, required);
        byte[] newArray = new byte[newCap];
        System.arraycopy(array, 0, newArray, 0, count);
        array = newArray;
    }

    if (byteArrayValue == null) {
        // Fill with null bytes (0)
        for (int i = 0; i < byteLength; i++) {
            array[count + i] = 0;
        }
    } else {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length - byteLength) {
            throw new IndexOutOfBoundsException(
                "byteOffset and byteLength exceed source array bounds");
        }
        System.arraycopy(byteArrayValue, byteOffset, array, count, byteLength);
    }

    count += byteLength;
    return this;
}

