public static String deleteAny(String inString, String charsToDelete) {
    if (inString == null) {
        return null;
    }
    if (charsToDelete == null || charsToDelete.isEmpty()) {
        return inString;
    }
    StringBuilder sb = new StringBuilder(inString.length());
    int len = inString.length();
    int toDelLen = charsToDelete.length();
    // Using a simple lookup; for performance with large char sets a BitSet could be used
    for (int i = 0; i < len; i++) {
        char c = inString.charAt(i);
        boolean shouldDelete = false;
        for (int j = 0; j < toDelLen; j++) {
            if (c == charsToDelete.charAt(j)) {
                shouldDelete = true;
                break;
            }
        }
        if (!shouldDelete) {
            sb.append(c);
        }
    }
    return sb.toString();
}

