public static byte convertHexDigit(byte b){
    // Convert an ASCII-encoded hex digit to its numeric value (0-15).
    // Acceptable characters: '0'-'9', 'a'-'f', 'A'-'F'.
    // Throw IllegalArgumentException for invalid input.
    if (b >= '0' && b <= '9') {
        return (byte)(b - '0');
    }
    if (b >= 'a' && b <= 'f') {
        return (byte)(10 + (b - 'a'));
    }
    if (b >= 'A' && b <= 'F') {
        return (byte)(10 + (b - 'A'));
    }
    throw new IllegalArgumentException("Invalid hex digit: " + (char)b);
}

private void addReverse(final InputStream[] files) {
    if (files == null) {
        throw new IllegalArgumentException("files array must not be null");
    }
    for (int i = files.length - 1; i >= 0; i--) {
        InputStream file = files[i];
        if (file == null) {
            continue;
        }
        try {
            add(file);  // assumes a suitable add(InputStream) method exists
        } catch (Exception e) {
            throw new RuntimeException("Failed to add file at index " + i, e);
        } finally {
            try {
                file.close();
            } catch (java.io.IOException ignored) {
                // ignore close exception
            }
        }
    }
}

private void check(String modelName) throws IllegalStateException {
    try {
        Class<?> clazz = Class.forName(modelName);
        java.util.List<Integer> indices = new java.util.ArrayList<>();
        for (java.lang.reflect.Field field : clazz.getDeclaredFields()) {
            for (java.lang.annotation.Annotation ann : field.getAnnotations()) {
                if (ann.annotationType().getName().equals("ShardKey")) {
                    try {
                        java.lang.reflect.Method indexMethod = ann.annotationType().getMethod("index");
                        Object idxObj = indexMethod.invoke(ann);
                        if (idxObj instanceof Number) {
                            indices.add(((Number) idxObj).intValue());
                        }
                    } catch (NoSuchMethodException ignored) {
                        // No index method; ignore this annotation
                    }
                }
            }
        }
        if (!indices.isEmpty()) {
            java.util.Collections.sort(indices);
            for (int i = 0; i < indices.size(); i++) {
                if (!indices.get(i).equals(i + 1)) {
                    throw new IllegalStateException("Sharding key indices are not continuous for model " + modelName);
                }
            }
        }
    } catch (ClassNotFoundException e) {
        throw new IllegalStateException("Model class not found: " + modelName, e);
    } catch (IllegalAccessException | java.lang.reflect.InvocationTargetException e) {
        throw new IllegalStateException("Failed to access sharding key metadata for model " + modelName, e);
    }
}

public byte readByte() throws IOException {
    // Validate that we still have data to read or can refill
    if (pos >= count) {
        // Try to refill the buffer
        try {
            count = fillBuffer(); // should return number of bytes read into buffer
            pos = 0;
        } catch (IOException e) {
            // Rethrow any IO errors that occur during refill
            throw e;
        }
        // If refill still yields no data, we've reached EOF
        if (count <= 0) {
            throw new IOException("End of stream");
        }
    }
    // Safely read the next byte
    return buffer[pos++];
}

@Override public Action inspect(AtmosphereResource r) {
    try {
