        // Silently handle any runtime issues (e.g., suspension not supported)
    }
    return Action.CONTINUE;
}

public double vertexWeight(Set<V> v) {
    // Input validation
    if (v == null) {
        throw new IllegalArgumentException("Vertex set 'v' must not be null");
    }
    // Assuming the graph is represented by a field called 'graph',
    // where each vertex maps to a collection of outgoing edges.
    // Each Edge object provides access to its target vertex and weight.
    try {
        if (graph == null || graph.isEmpty()) {
            return 0.0;
        }
        double sum = 0.0;
        for (Set<Edge<V>> edges : graph.values()) {
            for (Edge<V> e : edges) {
                if (v.equals(e.getTo())) {
                    sum += e.getWeight();
                }
            }
        }
        return sum;
    } catch (Exception e) {
        // Any unexpected runtime exception is wrapped in an IllegalArgumentException
        throw new IllegalArgumentException("Failed to compute vertex weight: " + e.getMessage(), e);
    }
}

public int compare(Object aObj1, Object aObj2) {
    // Handle identical references or both null
    if (aObj1 == aObj2) {
        return 0;
    }

    // Null handling – consider null less than any non‑null value
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }

    // Attempt natural ordering if both objects are of the same concrete type
    // and implement Comparable
    if (aObj1.getClass() == aObj2.getClass() && aObj1 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> comp = (Comparable<Object>) aObj1;
            return comp.compareTo(aObj2);
        } catch (ClassCastException e) {
            // Fall through to the generic handling below.
        }
    }

    // If objects are equal by equals() but not comparable, return 0
    if (aObj1.equals(aObj2)) {
        return 0;
    }

    // Non‑comparable objects cannot be ordered
    throw new ClassCastException(
        "Cannot compare objects of different or incomparable types: " 
        + aObj1.getClass() + " vs " + aObj2.getClass());
}

