public int appendLoopOnAppenders(LoggingEvent event){
    if(event == null){
        // No event to log; nothing to append
        return 0;
    }
    // Assume that this class implements AppenderAttachable and provides the method
    // getAllAppenders() that returns an Enumeration of all attached appenders.
    // If such a method is not available, subclasses should override this method.
    int appenderCount = 0;
    Enumeration<?> enc = null;
    try {
        enc = getAllAppenders();
    } catch (Exception ignore) {
        // getAllAppenders may throw an exception if the underlying implementation
        // doesn't support it; in that case simply return 0.
        return 0;
    }

    if(enc == null){
        return 0;
    }

    while(enc.hasMoreElements()){
        Object obj = enc.nextElement();
        if(!(obj instanceof Appender)){
            // Skip objects that are not appenders
            continue;
        }
        Appender appender = (Appender)obj;
        if(appender == null){
            continue;
        }
        try{
            appender.doAppend(event);
            appenderCount++;
        }catch (Exception ex){
            // Log the exception to the logger's own error handling mechanism
            // (e.g., LogLog.error) and continue with the next appender
            LogLog.error("Failed to append event to appender [" + appender + "].", ex);
        }
    }
    return appenderCount;
}

