int addConstantNameAndType(final String name, final String descriptor) {
    // Validate arguments
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }

    // Use a canonical key for the name/descriptor pair
    String key = name + '\u0000' + descriptor;

    try {
        // Check if we already have this entry
        Integer existingIndex = nameAndTypeIndexMap.get(key);
        if (existingIndex != null) {
            return existingIndex;
        }

        // Create the new constant pool entry
        ConstantNameAndTypeInfo newInfo = new ConstantNameAndTypeInfo(name, descriptor);

        // Add to the constant pool list
        int newIndex = constantPool.size();
        constantPool.add(newInfo);

        // Record the new entry in the lookup map
        nameAndTypeIndexMap.put(key, newIndex);

        return newIndex;
    } catch (Exception e) {
        // In practice you might want a more specific error handling strategy
        throw new RuntimeException("Failed to add ConstantNameAndType_info", e);
    }
}

