                    } else if (i + 3 < len &&
                               isHexDigit(input.charAt(i)) && isHexDigit(input.charAt(i + 1)) &&
                               isHexDigit(input.charAt(i + 2)) && isHexDigit(input.charAt(i + 3))) {
                        hexDigits = 4;
                    }
                    if (hexDigits > 0) {
                        String hex = input.substring(i, i + hexDigits);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                        } catch (NumberFormatException e) {
                            // Fallback: keep the raw representation
                            sb.append("\\x").append(hex);
                        }
                        i += hexDigits;
                    } else {
                        // Not a valid hex escape, keep literal
                        sb.append("\\x");
                    }
                    break;
                default:
                    // Any other escaped character is taken literally
                    sb.append(next);
                    break;
            }
        } else {
            sb.append(c);
            i++;
        }
    }

    return sb.toString();
}

