private boolean unlink(ListNodeImpl<E> node){
    if (node == null) {
        return false;
    }
    try {
        ListNodeImpl<E> prev = node.prev;
        ListNodeImpl<E> next = node.next;

        // Adjust previous node
        if (prev != null) {
            prev.next = next;
        } else {
            // node was head
            head = next;
        }

        // Adjust next node
        if (next != null) {
            next.prev = prev;
        } else {
            // node was tail
            tail = prev;
        }

        // Help GC by severing links
        node.prev = null;
        node.next = null;
        size--;
        return true;
    } catch (Exception e) {
        return false;
    }
}

