private String parseToken(final char[] terminators) {
    if (terminators == null) {
        throw new IllegalArgumentException("terminators cannot be null");
    }
    // Build the token incrementally.
    StringBuilder token = new StringBuilder();
    try {
        while (pos < length) {
            char current = input.charAt(pos);
            boolean isTerminator = false;
            for (char t : terminators) {
                if (current == t) {
                    isTerminator = true;
                    break;
                }
            }
            if (isTerminator) {
                break; // Stop parsing when a terminator is encountered.
            }
            token.append(current);
            pos++; // Advance to the next character.
        }
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception to signal parsing failure.
        throw new RuntimeException("Error parsing token", e);
    }
    return token.toString();
}

