private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null) {
        throw new IllegalArgumentException("bounds cannot be null");
    }
    int n = bounds.size();
    List<Integer> suffixSums = new ArrayList<>(n);
    // Initialize the list with placeholders
    for (int i = 0; i < n; i++) {
        suffixSums.add(0);
    }

    long runningSum = 0;
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        long current = (val == null) ? 0L : val.longValue();
        runningSum += current;
        // Store the suffix sum as an Integer; cast may truncate, but required by signature
        suffixSums.set(i, (int) runningSum);
    }

    long totalSum = runningSum;
    return new Pair<>(suffixSums, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null.");
    }
    int length = arr.length;
    if (from < 0 || to >= length || from > to) {
        throw new IllegalArgumentException(
            String.format("Invalid range: from=%d, to=%d for array length=%d.", from, to, length));
    }
    // No operation required when range consists of a single element
    if (from == to) {
        return;
    }
    int left = from;
    int right = to;
    while (left < right) {
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        return;
    }
    // Lock both lists to preserve atomicity. Use a consistent lock order to avoid dead‑locks.
    Object firstLock = System.identityHashCode(this) < System.identityHashCode(list) ? this : list;
    Object secondLock = firstLock == this ? list : this;
    synchronized (firstLock) {
        synchronized (secondLock) {
            // No-op if we’re instructed to move nodes to ourselves.
            if (this == list) {
                return;
            }
            // Perform the move. We iterate over the nodes in the source list, detach each, and re‑attach it to this list.
            // The sentinel nodes are assumed to be named head and tail and are never moved.
            try {
                ListNodeImpl<E> node = list.head.next; // head is a sentinel node
                while (node != list.tail) {
                    ListNodeImpl<E> next = node.next;
                    list.removeListNode(node);
                    this.addListNode(node);
                    node = next;
                }
            } catch (Exception e) {
                // Wrap any unexpected error in an IllegalStateException to signal failure of the atomic move.
                throw new IllegalStateException("Failed to atomically move list nodes", e);
            }
        }
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
