private List<Pair<List<Pair<Integer,Integer>>, E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>, E>> globalList = new ArrayList<>();
    if (graph == null) {
        return globalList;
    }
    try {
        for (E edge : graph.edgeSet()) {
            // obtain the two endpoints of the current edge
            Integer src = null;
            Integer tgt = null;
            try {
                src = graph.getEdgeSource(edge);
                tgt = graph.getEdgeTarget(edge);
            } catch (Exception e) {
                // Edge does not expose source/target; skip this edge
                continue;
            }

            // Collect the IDs of all neighbors of both endpoints
            Set<Integer> neighborSet = new HashSet<>();
            for (E eFromSrc : graph.edgesOf(src)) {
                if (!eFromSrc.equals(edge)) {
                    Integer nbr = graph.getEdgeSource(eFromSrc).equals(src) ?
                                   graph.getEdgeTarget(eFromSrc) :
                                   graph.getEdgeSource(eFromSrc);
                    neighborSet.add(nbr);
                }
            }
            for (E eFromTgt : graph.edgesOf(tgt)) {
                if (!eFromTgt.equals(edge)) {
                    Integer nbr = graph.getEdgeSource(eFromTgt).equals(tgt) ?
                                   graph.getEdgeTarget(eFromTgt) :
                                   graph.getEdgeSource(eFromTgt);
                    neighborSet.add(nbr);
                }
            }

            // Build a list of all pairwise combinations of neighbours
            List<Pair<Integer,Integer>> separator = new ArrayList<>();
            List<Integer> neighbors = new ArrayList<>(neighborSet);
            for (int i = 0; i < neighbors.size(); i++) {
                for (int j = i + 1; j < neighbors.size(); j++) {
                    separator.add(new Pair<>(neighbors.get(i), neighbors.get(j)));
                }
            }

            // Append the pair consisting of the separator list and the original edge
            globalList.add(new Pair<>(separator, edge));
        }
    } catch (Exception e) {
        // In case of any unexpected failure, return what we have so far
    }
    return globalList;
}

