        if (newCap < pos + 4) {
            newCap = pos + 4;
        }
        byte[] newData = new byte[newCap];
        System.arraycopy(data, 0, newData, 0, pos);
        newData[newPos] = (byte)(intValue >>> 24);
        newData[newPos + 1] = (byte)(intValue >>> 16);
        newData[newPos + 2] = (byte)(intValue >>> 8);
        newData[newPos + 3] = (byte)intValue;
        data = newData;
        pos += 4;
        capacity = newCap;
    }
    return this;
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    try {
        // Validate parameters
        if (a == null || b == null) {
            return false;
        }
        if (count < 0) {
            return false;
        }
        if (count == 0) {
            return true;
        }
        if (count > a.length || count > b.length) {
            return false;
        }

        // Compare byte by byte
        for (int i = 0; i < count; i++) {
            if (a[i] != b[i]) {
                return false;
            }
        }
        return true;
    } catch (Exception e) {
        // Any unexpected exception results in false
        return false;
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("buf cannot be null");
    }
    // The source name string is assumed to be stored in an instance field named ‘name’.
    // This method appends the abbreviation of the name (starting from the supplied index)
    // to the provided StringBuffer.
    try {
        if (name == null || name.isEmpty()) {
            return;
        }
        // Clamp the start index to a valid range
        int start = Math.max(0, Math.min(nameStart, name.length()));
        if (start == name.length()) {
            return; // nothing to abbreviate
        }
        String remaining = name.substring(start).trim();
        if (remaining.isEmpty()) {
            return;
        }
        // Split by whitespace; optionally hyphens could be treated as separators too.
        String[] words = remaining.split("\\s+");
        for (String word : words) {
            if (!word.isEmpty()) {
                buf.append(word.charAt(0));
            }
        }
    } catch (Exception e) {
        // Wrap any unexpected exception in a RuntimeException to avoid unchecked errors silently.
        throw new RuntimeException("Failed to abbreviate name", e);
    }
}

