private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    // A clique with 0 or 1 vertices is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    // Convert to array to avoid repeated iterator overhead
    V[] verticesArray = (V[]) vertices.toArray(new Object[0]);

    for (int i = 0; i < verticesArray.length; i++) {
        V v1 = verticesArray[i];
        if (!graph.containsVertex(v1)) {
            // Vertex not in the graph – cannot be part of a clique
            return false;
        }
        for (int j = i + 1; j < verticesArray.length; j++) {
            V v2 = verticesArray[j];
            if (!graph.containsVertex(v2)) {
                return false;
            }
            try {
                if (!graph.containsEdge(v1, v2)) {
                    return false;
                }
            } catch (IllegalArgumentException | NullPointerException e) {
                // Any exception related to edge querying means the edge is not present
                return false;
            }
        }
    }
    return true;
}

