    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (Integer key : keys) {
        if (key == null) {
            lowerBounds.add(null);
            continue;
        }
        Integer maxLower = null;
        for (Integer candidate : keys) {
            if (candidate == null || candidate.intValue() >= key.intValue()) {
                continue;
            }
            if (maxLower == null || candidate.intValue() > maxLower.intValue()) {
                maxLower = candidate;
            }
        }
        lowerBounds.add(maxLower);
    }
    return lowerBounds;
}

