private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    for (K key : keys) {
        try {
            if (key == null) {
                bounds.add(Integer.MAX_VALUE);
            } else if (key instanceof Number) {
                bounds.add(((Number) key).intValue() + 1);
            } else {
                bounds.add(key.hashCode());
            }
        } catch (Exception e) {
            // If any unexpected exception occurs, use Integer.MAX_VALUE as a safe fallback.
            bounds.add(Integer.MAX_VALUE);
        }
    }
    return bounds;
}

public static String encodeTemplateNames(String s) {
    try {
        if (s == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '{') {
                sb.append("%7B");
            } else if (c == '}') {
                sb.append("%7D");
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    } catch (Exception e) {
        // In case of any unexpected issue, return the original string
        return s;
    }
}

