public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non‑null");
    }
    // If the relative path is empty just return the original path
    if (relativePath.isEmpty()) {
        return path;
    }

    boolean leadingSlash = path.startsWith("/");
    boolean pathEndsWithSlash = path.endsWith("/");
    boolean relativeEndsWithSlash = relativePath.endsWith("/");

    // Split the original path into components, ignoring empty parts caused by leading '/'
    String[] pathParts = path.split("/");
    ArrayList<String> stack = new ArrayList<>();

    // Determine the base directory: if the path ends with '/' it is already a directory,
    // otherwise drop the last component (treated as a file name)
    int limit = pathEndsWithSlash ? pathParts.length : Math.max(pathParts.length - 1, 0);
    for (int i = 0; i < limit; i++) {
        if (!pathParts[i].isEmpty()) {
            stack.add(pathParts[i]);
        }
    }

    // Resolve the relative path segments
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue; // no change
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            } // if stack empty and leadingSlash true, stay at root
        } else {
            stack.add(part);
        }
    }

    // Build the resulting path string
    StringBuilder sb = new StringBuilder();
    if (leadingSlash) {
        sb.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) sb.append("/");
        sb.append(stack.get(i));
    }

    // Ensure trailing '/' if the relative path ended with one
    if (relativeEndsWithSlash && sb.length() > 0 && sb.charAt(sb.length() - 1) != '/') {
        sb.append("/");
    } else if (sb.length() == 0 && leadingSlash) { // root
        sb.append("/");
    }

    return sb.toString();
}

