public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    try {
        int lastDot = filename.lastIndexOf('.');
        if (lastDot == -1) {
            return -1;
        }
        int lastSepSlash = filename.lastIndexOf('/');
        int lastSepBack = filename.lastIndexOf('\\');
        int lastSep = Math.max(lastSepSlash, lastSepBack);
        if (lastSep > lastDot) {
            return -1;
        }
        return lastDot;
    } catch (Exception e) {
        return -1;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        // Calculate the duration elapsed since the given timestamp
        long elapsed = System.currentTimeMillis() - timestamp;
        // If the elapsed time exceeds the expiration threshold, consider it expired
        return elapsed > expiredThreshold;
    } catch (Exception e) {
        // On unexpected errors, default to not expiring to prevent accidental eviction
        return false;
    }
}

