public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Null checks
    if (str == null || substring == null) {
        return false;
    }
    // Negative start index is invalid
    if (index < 0) {
        return false;
    }
    // If substring is empty, it matches at any valid index up to the end of str
    int subLen = substring.length();
    if (subLen == 0) {
        return index <= str.length();
    }
    // The substring must fit within the original string from the given index
    if (index + subLen > str.length()) {
        return false;
    }
    // Compare characters
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event){
    if (event == null) {
        return;
    }
    String message = "";
    Object msgObj = event.getMessage();
    if (msgObj != null) {
        message = msgObj.toString();
    }

    // Iterate over a copy to safely modify the collection while iterating
    for (Iterator<PrintWriter> it = writers.iterator(); it.hasNext(); ) {
        PrintWriter out = it.next();
        try {
            out.print(message);
            out.print(System.lineSeparator());
            out.flush();
        } catch (Exception e) {
            // If a writer fails, close it and remove from the list to avoid repeated failures
            try {
                out.close();
            } catch (Exception closeEx) {
                // Ignore secondary close failures
            }
            it.remove();
            System.err.println("Failed to send log to a connected client: " + e.getMessage());
        }
    }
}

