private String buildContentRange() {
    try {
        java.lang.reflect.Field startField = this.getClass().getDeclaredField("rangeStart");
        java.lang.reflect.Field endField = this.getClass().getDeclaredField("rangeEnd");
        java.lang.reflect.Field totalField = this.getClass().getDeclaredField("fileSize");
        startField.setAccessible(true);
        endField.setAccessible(true);
        totalField.setAccessible(true);
        Object startObj = startField.get(this);
        Object endObj = endField.get(this);
        Object totalObj = totalField.get(this);
        if (startObj == null || endObj == null || totalObj == null) {
            throw new IllegalStateException("Range parameters are not initialized");
        }
        long start = (startObj instanceof Number) ? ((Number) startObj).longValue()
                : Long.parseLong(startObj.toString());
        long end = (endObj instanceof Number) ? ((Number) endObj).longValue()
                : Long.parseLong(endObj.toString());
        long total = (totalObj instanceof Number) ? ((Number) totalObj).longValue()
                : Long.parseLong(totalObj.toString());
        if (start < 0 || end < start || total <= 0) {
            throw new IllegalArgumentException("Invalid range values for Content-Range header");
        }
        return String.format("bytes %d-%d/%d", start, end, total);
    } catch (NoSuchFieldException | IllegalAccessException e) {
        throw new RuntimeException("Unable to build Content-Range header", e);
    }
}
